DELETE FROM moderation_versions WHERE (kind,version_id) IN (SELECT kind,version_id FROM moderation_contributors WHERE actor_id BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004');
DELETE FROM audit_logs WHERE actor_user_id BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004'
    AND action IN ('QUESTION_ARCHIVED','QUESTION_GROUP_ARCHIVED','QUESTION_CREATED','QUESTION_UPDATED','QUESTION_GROUP_CREATED','QUESTION_GROUP_UPDATED','CONTENT_SUBMITTED','CONTENT_APPROVED','CONTENT_RETURNED','CONTENT_APPROVAL_REVOKED','CONTENT_PUBLISHED','QUESTION_SUBMITTED','QUESTION_APPROVED','QUESTION_RETURNED','QUESTION_APPROVAL_REVOKED','QUESTION_PUBLISHED','QUESTION_GROUP_SUBMITTED','QUESTION_GROUP_APPROVED','QUESTION_GROUP_RETURNED','QUESTION_GROUP_APPROVAL_REVOKED','QUESTION_GROUP_PUBLISHED');

DELETE FROM question_resources WHERE question_version_id IN (SELECT v.question_version_id FROM question_versions v JOIN questions q USING(question_id) WHERE q.created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004');
DELETE FROM question_choices WHERE question_version_id IN (SELECT v.question_version_id FROM question_versions v JOIN questions q USING(question_id) WHERE q.created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004');
UPDATE questions SET current_published_version_id=NULL WHERE created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004';
DELETE FROM question_versions WHERE question_id IN (SELECT question_id FROM questions WHERE created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004');
DELETE FROM questions WHERE created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004';
DELETE FROM question_group_version_resources WHERE group_version_id IN (SELECT v.group_version_id FROM question_group_versions v JOIN question_groups g USING(group_id) WHERE g.created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004' OR g.group_id='c3000000-0000-0000-0000-000000000999');
UPDATE question_groups SET current_published_version_id=NULL WHERE created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004' OR group_id='c3000000-0000-0000-0000-000000000999';
DELETE FROM question_group_versions WHERE group_id IN (SELECT group_id FROM question_groups WHERE created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004' OR group_id='c3000000-0000-0000-0000-000000000999');
DELETE FROM question_groups WHERE created_by BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004' OR group_id='c3000000-0000-0000-0000-000000000999';
DELETE FROM media_reuse_grants WHERE media_id BETWEEN 'b3000000-0000-0000-0000-000000000001' AND 'b3000000-0000-0000-0000-000000000009';
DELETE FROM media_resources WHERE resource_id BETWEEN 'b3000000-0000-0000-0000-000000000001' AND 'b3000000-0000-0000-0000-000000000009';
DELETE FROM auth_sessions WHERE user_id BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004';
DELETE FROM user_roles WHERE user_id BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004';
DELETE FROM users WHERE user_id BETWEEN 'a3000000-0000-0000-0000-000000000001' AND 'a3000000-0000-0000-0000-000000000004';
